      { role: "assistant", content: "Real response with durable facts." },
      { role: "user", content: "ok" },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(1);
    expect(result[0].content).toBe("Real response with durable facts.");
  });

  it("strips noise fragments but keeps the rest", () => {
    const messages = [
      {
        role: "user",
        content: `Conversation info (untrusted metadata):
\`\`\`json
{
  "message_id": "123",
  "sender": "456"
}
\`\`\`

What is the deployment plan?`,
      },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(1);
    expect(result[0].content).toBe("What is the deployment plan?");
  });

  it.each(["user", "assistant"])("preserves long %s messages through extraction preparation", (role) => {
    const content = "Repository detail. ".repeat(600) + "Final requirement. password=<REDACTED>";
    const result = createMemoryLifecycle().prepareConversation(
      filterMessagesForExtraction([{ role, content }]),
    );
    expect(result).toEqual([
      { role, content: content.replace("hidden-extraction-secret", "[REDACTED]") },
    ]);
  });

  it("returns empty array when all messages are noise", () => {
    const messages = [
      { role: "user", content: "NO_REPLY" },
      { role: "user", content: "ok" },
      { role: "user", content: "Current time: Friday, February 20th, 2026" },
    ];
    expect(filterMessagesForExtraction(messages)).toHaveLength(0);
  });

  it("handles a realistic mixed payload", () => {
    const messages = [
      {
        role: "user",
        content: "Pre-compaction memory flush. Store durable memories now.",
      },
      {
        role: "assistant",
        content:
          "## What I Accomplished\n\nDeployed the API to production with Vercel.",
      },
      { role: "user", content: "sir" },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(1);
    expect(result[0].content).toContain("Deployed the API");
  });

  it("drops generic assistant acknowledgments", () => {
    const messages = [
      {
        role: "user",
        content:
          "[ASSISTANT]: Updated the Google Sheet with truth-based scripts.",
      },
      {
        role: "assistant",
        content: "I see you've shared an update. How can I help?",
      },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(1);
    expect(result[0].role).toBe("user");
    expect(result[0].content).toContain("Google Sheet");
  });

  it("returns only assistant messages when all user messages are noise", () => {
    // This scenario triggers the #2 guard: no user content remains
    const messages = [
      { role: "user", content: "ok" },
      { role: "user", content: "HEARTBEAT_OK" },
      { role: "assistant", content: "I deployed the API to production." },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(1);
    expect(result[0].role).toBe("assistant");
    // The capture hook checks: if no user messages remain, skip add()
    expect(result.some((m) => m.role === "user")).toBe(false);
  });

  it("keeps substantive assistant messages even with generic opener", () => {
    const messages = [
      { role: "user", content: "What did you do?" },
      {
        role: "assistant",
        content:
          "I deployed the API to production and configured the webhook endpoints for Stripe integration.",
      },
    ];
    const result = filterMessagesForExtraction(messages);
    expect(result).toHaveLength(2);
  });
});

// ---------------------------------------------------------------------------
// Auto-recall threshold filtering
// The recall hook in index.ts filters search results using cfg.searchThreshold.
// These tests verify the threshold is honored and no hardcoded floor overrides it.
// ---------------------------------------------------------------------------
describe("auto-recall threshold respects cfg.searchThreshold", () => {
  const typicalV3Results = [
    { id: "1", score: 0.553, memory: "User prefers dark mode" },
    { id: "2", score: 0.496, memory: "User works on mem0 project" },
    { id: "3", score: 0.471, memory: "User likes TypeScript" },
    { id: "4", score: 0.45, memory: "User's timezone is PST" },
    { id: "5", score: 0.42, memory: "User uses VS Code" },
    { id: "6", score: 0.35, memory: "User mentioned family trip" },
  ];

  function applyThresholdFilter(
    results: typeof typicalV3Results,
    searchThreshold: number,
  ) {
    return results.filter((r) => (r.score ?? 0) >= searchThreshold);
  }

  it("default 0.5 threshold returns results scoring >= 0.5", () => {
    const filtered = applyThresholdFilter(typicalV3Results, 0.5);
    expect(filtered).toHaveLength(1);
    expect(filtered[0].id).toBe("1");
  });

  it("threshold 0.4 returns results scoring >= 0.4", () => {
    const filtered = applyThresholdFilter(typicalV3Results, 0.4);
    expect(filtered).toHaveLength(5);
  });

  it("threshold 0.3 returns all results", () => {
    const filtered = applyThresholdFilter(typicalV3Results, 0.3);
    expect(filtered).toHaveLength(6);
  });

  it("threshold 0.6 correctly filters everything below", () => {
    const filtered = applyThresholdFilter(typicalV3Results, 0.6);
    expect(filtered).toHaveLength(0);
  });

  it("threshold 0 returns all results", () => {
    const filtered = applyThresholdFilter(typicalV3Results, 0);
    expect(filtered).toHaveLength(6);
  });
});

import uuid
